"use client";

import { useEffect, useState } from "react";

import { PROCESS_PANELS } from "@/components/sections/process-panels";
import { processSteps, processTabLabels } from "@/config/content";
import { cn } from "@/lib/utils";

const STEP_DURATION_MS = 7000;

function Process() {
  const [step, setStep] = useState(0);

  // Restarts the 7s window on every state change, whether it came from the
  // auto-advance tick below or a manual tab click — mirrors the original
  // `startSteps()` restart-on-select behavior.
  useEffect(() => {
    const id = window.setInterval(() => {
      setStep((current) => (current + 1) % processSteps.length);
    }, STEP_DURATION_MS);
    return () => window.clearInterval(id);
  }, [step]);

  const ActivePanel = PROCESS_PANELS[step];
  const activeContent = processSteps[step];

  return (
    <section
      id="process"
      className="border-border border-y bg-[var(--tb-field)] text-[#eef2f6]"
    >
      <div className="mx-auto max-w-[1280px] px-6 py-22 md:px-10">
        <div className="mb-14 flex flex-col gap-12 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h6 className="text-accent-300 mb-3.5">02 — Process</h6>
            <h2 className="text-[2.875rem] tracking-[-0.02em] text-white">
              TWO BITS HOLD FOUR STATES
            </h2>
          </div>
          <p className="text-accent-300 max-w-[34ch] font-mono text-[13px] leading-loose">
            00 → 01 → 10 → 11. Every engagement runs the same four phases, in
            the same order, with a demo at each boundary.
          </p>
        </div>

        <div className="mb-13 flex flex-wrap justify-center gap-3.5">
          {processSteps.map((processStep, i) => {
            const active = i === step;
            return (
              <button
                key={processStep.state}
                type="button"
                onClick={() => setStep(i)}
                className={cn(
                  "hover:border-accent-400 relative flex items-center gap-2.5 border border-white/16 px-5.5 py-3.25 font-mono text-xs tracking-[0.16em] text-[#eef2f6] transition-opacity",
                  active ? "opacity-100" : "opacity-50",
                )}
              >
                <span className="text-accent-400 text-[15px]">
                  {processStep.code}
                </span>
                <span>{processTabLabels[i]}</span>
                {active && (
                  <>
                    <span
                      aria-hidden="true"
                      className="border-primary pointer-events-none absolute -inset-px border"
                    />
                    <span
                      key={step}
                      aria-hidden="true"
                      className="animate-tb-bar bg-primary absolute inset-x-0 bottom-0 h-0.5 origin-left"
                      style={{ animationDuration: `${STEP_DURATION_MS}ms` }}
                    />
                  </>
                )}
              </button>
            );
          })}
        </div>

        <div className="grid min-h-95 items-center gap-16 md:grid-cols-[1fr_1.15fr]">
          <div key={`copy-${step}`} className="animate-tb-pop">
            <div className="text-accent-400 mb-5.5 font-mono text-xs tracking-[0.2em]">
              state {activeContent.state}
            </div>
            <h3 className="mb-4.5 text-[2.75rem] leading-[1.02] tracking-[-0.02em] text-white">
              {activeContent.title}
            </h3>
            <p className="mb-6.5 max-w-[42ch] text-base leading-relaxed text-white/78">
              {activeContent.description}
            </p>
            <div className="grid gap-2.25 text-sm text-white/82">
              {activeContent.bullets.map((bullet) => (
                <div key={bullet} className="flex gap-2.5">
                  <span className="text-accent-400">+</span>
                  <span>{bullet}</span>
                </div>
              ))}
            </div>
          </div>

          <div key={`panel-${step}`} className="animate-tb-pop">
            <ActivePanel />
          </div>
        </div>
      </div>
    </section>
  );
}

export { Process };
