import { Blueprint } from "@/components/blueprint/blueprint";
import { findings } from "@/config/content";

const panelBorder = "border-white/18";

function ScopePanel() {
  return (
    <Blueprint className={`min-h-80 border ${panelBorder} p-6.5 pb-7`}>
      <div className="mb-6.5 flex items-center gap-3 font-mono text-[13px]">
        <span className="animate-tb-spin border-accent-400 size-3.75 rounded-full border-[1.5px] border-t-transparent" />
        <span className="text-accent-300">Mapping</span>
        <span className="text-white/70">current system…</span>
      </div>
      <div className="mb-3.5 grid grid-cols-2 gap-3.5">
        {["Stack audit", "Attack surface"].map((label, i) => (
          <div
            key={label}
            className={`flex items-center gap-3 border ${panelBorder} px-4 py-3.75 opacity-0`}
            style={{ animation: `tb-pop 0.5s ease-out ${0.6 * (i + 1)}s both` }}
          >
            <span className="text-accent-400 font-mono text-sm">✓</span>
            <span className="text-[13.5px]">{label}</span>
          </div>
        ))}
      </div>
      <div
        className={`flex items-center justify-between gap-4 border ${panelBorder} px-4 py-3.75 opacity-0`}
        style={{ animation: "tb-pop 0.5s ease-out 1.8s both" }}
      >
        <span className="flex items-center gap-3">
          <span className="text-accent-400 font-mono text-sm">✓</span>
          <span className="text-[13.5px]">Scope draft</span>
        </span>
        <span className="bg-primary text-accent-900 px-2.5 py-0.75 font-mono text-[11px] tracking-[0.1em]">
          READY
        </span>
      </div>
    </Blueprint>
  );
}

function ShapePanel() {
  return (
    <Blueprint className={`min-h-80 border ${panelBorder} p-6.5 pb-7`}>
      <div className="text-accent-300 mb-5.5 flex items-center justify-between font-mono text-xs tracking-[0.12em]">
        <span>drawing — checkout.flow</span>
        <span className="text-white/55">v3</span>
      </div>
      <div className="grid gap-3">
        <div className="flex gap-2.5">
          <span
            className="h-6.5 w-6.5 origin-left bg-white/22 opacity-0"
            style={{ animation: "tb-bar 0.4s ease-out 0.1s both" }}
          />
          <span
            className="h-6.5 flex-1 origin-left bg-white/12 opacity-0"
            style={{ animation: "tb-bar 0.5s ease-out 0.25s both" }}
          />
          <span
            className="bg-primary h-6.5 w-18.5 origin-left opacity-0"
            style={{ animation: "tb-bar 0.4s ease-out 0.45s both" }}
          />
        </div>
        <div className="flex gap-3">
          <div className="grid flex-1 gap-2.5">
            <span
              className={`block h-24 origin-left border ${panelBorder} opacity-0`}
              style={{ animation: "tb-bar 0.6s ease-out 0.6s both" }}
            />
            <span
              className="block h-3 w-[78%] origin-left bg-white/14 opacity-0"
              style={{ animation: "tb-bar 0.5s ease-out 1s both" }}
            />
            <span
              className="block h-3 w-[56%] origin-left bg-white/14 opacity-0"
              style={{ animation: "tb-bar 0.5s ease-out 1.15s both" }}
            />
          </div>
          <div className="grid w-33 content-start gap-2.5">
            <span
              className={`block h-8.5 origin-left border ${panelBorder} opacity-0`}
              style={{ animation: "tb-bar 0.4s ease-out 0.8s both" }}
            />
            <span
              className={`block h-8.5 origin-left border ${panelBorder} opacity-0`}
              style={{ animation: "tb-bar 0.4s ease-out 0.95s both" }}
            />
            <span
              className="bg-primary/55 block h-8.5 origin-left opacity-0"
              style={{ animation: "tb-bar 0.4s ease-out 1.1s both" }}
            />
          </div>
        </div>
        <div
          className="text-accent-300 flex items-center gap-2.5 font-mono text-[11.5px] opacity-0"
          style={{ animation: "tb-pop 0.5s ease-out 1.5s both" }}
        >
          <span className="bg-primary size-2" />
          <span>threat model attached — 7 flows covered</span>
        </div>
      </div>
    </Blueprint>
  );
}

const BUILD_LINES = [
  { delay: 0.2, steps: 26, text: "export async function POST(req: Request) {" },
  {
    delay: 0.9,
    steps: 28,
    indent: true,
    text: "const body = schema.parse(await req.json());",
  },
  { delay: 1.6, steps: 22, indent: true, text: "await requireSession(req);" },
  {
    delay: 2.2,
    steps: 30,
    indent: true,
    text: "const order = await db.order.create({ data: body });",
  },
  {
    delay: 2.9,
    steps: 24,
    indent: true,
    text: "return Response.json(order, { status: 201 });",
  },
  { delay: 3.5, steps: 2, text: "}" },
];

function BuildPanel() {
  return (
    <Blueprint className={`min-h-80 border ${panelBorder}`}>
      <div
        className={`flex items-center gap-2 border-b ${panelBorder} px-4.5 py-3`}
      >
        <span className="bg-accent-400 size-2" />
        <span className="border-accent-400 size-2 border" />
        <span className="text-accent-300 ml-2 font-mono text-[11.5px] tracking-wide">
          app/api/orders/route.ts
        </span>
      </div>
      <div className="px-4.5 py-5 pb-6 font-mono text-[12.5px] leading-loose text-[#e9eef4]">
        {BUILD_LINES.map((line, i) => (
          <div
            key={i}
            className="animate-tb-type whitespace-nowrap"
            style={{
              animationDuration: `${line.steps * 0.023}s`,
              animationTimingFunction: `steps(${line.steps})`,
              animationDelay: `${line.delay}s`,
            }}
          >
            {line.indent && "\u00A0\u00A0"}
            {line.text}
          </div>
        ))}
        <div
          className="mt-3.5 flex items-center gap-2.5 opacity-0"
          style={{ animation: "tb-pop 0.5s ease-out 3.9s both" }}
        >
          <span className="text-accent-300">✓ 214 tests passed</span>
          <span className="text-white/55">staging deployed</span>
          <span
            className="animate-tb-blink bg-accent-300 inline-block h-3.5 w-1.75"
            style={{ animationDelay: "4.4s" }}
          />
        </div>
      </div>
    </Blueprint>
  );
}

function HardenPanel() {
  return (
    <Blueprint className={`min-h-80 border ${panelBorder} p-6`}>
      <div className="text-accent-300 mb-5 flex items-center justify-between font-mono text-xs tracking-[0.12em]">
        <span>retest — findings</span>
        <span className="text-white/55">3 of 3</span>
      </div>
      <div className="grid gap-3.5">
        {findings.map((finding, i) => (
          <div
            key={finding.title}
            className={`border ${panelBorder} px-4 py-3.75 opacity-0`}
            style={{ animation: `tb-pop 0.5s ease-out ${0.2 + i * 0.5}s both` }}
          >
            <div className="mb-3 flex items-center justify-between gap-3.5">
              <span className="text-[13.5px]">{finding.title}</span>
              <span className="text-accent-300 font-mono text-[11px] tracking-[0.1em]">
                {finding.severity}
              </span>
            </div>
            <div className="h-1 bg-white/14">
              <span
                className="bg-primary block h-full w-full origin-left opacity-0"
                style={{
                  animation: `tb-bar 1.1s ease-out ${0.5 + i * 0.6}s both`,
                }}
              />
            </div>
          </div>
        ))}
        <div
          className="text-accent-300 flex items-center gap-2.5 font-mono text-xs opacity-0"
          style={{ animation: "tb-pop 0.5s ease-out 2.6s both" }}
        >
          <span className="bg-primary size-2" />
          <span>0 open findings — cleared for release</span>
        </div>
      </div>
    </Blueprint>
  );
}

const PROCESS_PANELS = [ScopePanel, ShapePanel, BuildPanel, HardenPanel];

export { PROCESS_PANELS };
