"use client";

import { useState } from "react";

import { ServiceIcon } from "@/components/sections/service-icon";
import { Blueprint } from "@/components/blueprint/blueprint";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { serviceGroups } from "@/config/content";
import { cn } from "@/lib/utils";
import type { ServiceTrack } from "@/types";

function Services() {
  const [track, setTrack] = useState<ServiceTrack>("all");

  const visibleGroups = serviceGroups.filter(
    (group) => track === "all" || group.track === track,
  );

  return (
    <section
      id="services"
      className="mx-auto max-w-[1280px] px-6 py-24 md:px-10"
    >
      <div className="mb-11 flex flex-col items-start justify-between gap-10 sm:flex-row sm:items-end">
        <div>
          <h6 className="mb-3.5 text-[var(--tb-ink-accent)]">01 — Services</h6>
          <h2 className="max-w-[22ch] text-[2.875rem] tracking-[-0.02em]">
            FOUR SERVICES, TWO INSTINCTS
          </h2>
        </div>

        <div className="flex flex-col items-end gap-2.5">
          <span className="text-muted-foreground font-mono text-[10px] tracking-[0.18em] uppercase">
            Flip a bit
          </span>
          <ToggleGroup
            value={[track]}
            onValueChange={(values) => {
              const next = values[0] as ServiceTrack | undefined;
              if (next) setTrack(next);
            }}
            variant="outline"
            spacing={0}
            aria-label="Filter services"
          >
            <ToggleGroupItem
              value="all"
              className="data-[pressed]:bg-primary data-[pressed]:text-primary-foreground rounded-none text-xs"
            >
              ALL
            </ToggleGroupItem>
            <ToggleGroupItem
              value="build"
              className="data-[pressed]:bg-primary data-[pressed]:text-primary-foreground rounded-none text-xs"
            >
              1 · BUILD
            </ToggleGroupItem>
            <ToggleGroupItem
              value="secure"
              className="data-[pressed]:bg-primary data-[pressed]:text-primary-foreground rounded-none text-xs"
            >
              0 · SECURE
            </ToggleGroupItem>
          </ToggleGroup>
        </div>
      </div>

      <div
        className={cn(
          "grid items-start gap-7",
          track === "all" ? "md:grid-cols-2" : "mx-auto max-w-180 grid-cols-1",
        )}
      >
        {visibleGroups.map((group) => (
          <div key={group.track}>
            <div
              className={cn(
                "mb-6 flex items-baseline gap-3.5 border-b-2 pb-3",
                group.track === "build"
                  ? "border-primary"
                  : "border-foreground",
              )}
            >
              <span
                className={cn(
                  "font-heading text-4xl leading-none",
                  group.track === "build" && "text-primary",
                )}
              >
                {group.digit}
              </span>
              <span className="font-heading text-xl tracking-[0.1em]">
                {group.label}
              </span>
              <span className="text-muted-foreground ml-auto font-mono text-[11px]">
                {group.sublabel}
              </span>
            </div>

            <div className="grid gap-5">
              {group.services.map((service) => (
                <Blueprint
                  key={service.code}
                  className="border-border hover:border-primary hover:bg-primary/4 border p-6.5 transition-colors"
                >
                  <div className="mb-3.5 flex items-start justify-between gap-5">
                    <ServiceIcon icon={service.icon} />
                    <span className="text-foreground/45 font-mono text-[11px]">
                      {service.code}
                    </span>
                  </div>
                  <h3 className="mb-2 text-[1.7rem]">{service.title}</h3>
                  <p className="mb-3.5 text-[14.5px] opacity-[0.82]">
                    {service.description}
                  </p>
                  <div className="flex flex-wrap gap-1.5">
                    {service.tags.map((tag) => (
                      <span
                        key={tag}
                        className="border-primary text-primary border px-2.5 py-0.75 text-[11px]"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                </Blueprint>
              ))}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export { Services };
