"use client";

import type { ComponentProps } from "react";

import { useScramble } from "@/hooks/use-scramble";

interface ScrambleLinkProps extends Omit<ComponentProps<"a">, "children"> {
  children: string;
}

/** A nav link whose label "decodes" from binary/hex noise on hover. */
function ScrambleLink({ children, onMouseEnter, ...props }: ScrambleLinkProps) {
  const [display, trigger] = useScramble(children);

  return (
    <a
      {...props}
      onMouseEnter={(event) => {
        trigger();
        onMouseEnter?.(event);
      }}
    >
      {display}
    </a>
  );
}

interface ScrambleTextProps extends Omit<ComponentProps<"span">, "children"> {
  text: string;
}

/**
 * Non-link version of the same "decode" hover effect, for plain text —
 * service titles, process tabs, stack chips, etc. Trigger fires whenever
 * the pointer enters this span (or an ancestor forwards `onMouseEnter`).
 */
function ScrambleText({ text, onMouseEnter, ...props }: ScrambleTextProps) {
  const [display, trigger] = useScramble(text);

  return (
    <span
      {...props}
      onMouseEnter={(event) => {
        trigger();
        onMouseEnter?.(event);
      }}
    >
      {display}
    </span>
  );
}

export { ScrambleLink, ScrambleText };
